/** Test images (CMS-10), base64 so the Workers test pool can load them without file access. */
const b64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
/** 1200×600 photo (JPEG). 300×150 copies as WebP/AVIF. A 100×200 JPEG (top half red, bottom half blue) with EXIF orientation 6: displayed 200×100, left blue, right red. */
export const photoJpeg = b64("");
export const photoWebp = b64("");
export const photoAvif = b64("");
export const rotatedJpeg = b64("");
